from PIL import Image
im=Image.open('/home/robot/captures/top_003.png').convert('L')
w,h=im.size
pix=im.load()
# threshold dark < 80 maybe includes table background and bores, pin tray holes, print?
mask=[[0]*w for _ in range(h)]
for y in range(h):
    for x in range(w):
        if pix[x,y]<80:
            mask[y][x]=1
# BFS connected components, 4-neighbor
seen=[[False]*w for _ in range(h)]
comps=[]
for y in range(h):
    for x in range(w):
        if mask[y][x] and not seen[y][x]:
            stack=[(x,y)]; seen[y][x]=True
            xs=[]; ys=[]
            while stack:
                xx,yy=stack.pop()
                xs.append(xx); ys.append(yy)
                for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx,ny=xx+dx,yy+dy
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not seen[ny][nx]:
                        seen[ny][nx]=True; stack.append((nx,ny))
            comps.append((len(xs), (sum(xs)/len(xs), sum(ys)/len(ys)), min(xs),max(xs),min(ys),max(ys)))
# print large comps
for c in sorted(comps, reverse=True)[:30]:
    area,(cx,cy),x0,x1,y0,y1=c
    print(f'area={area} centroid=({cx:.1f},{cy:.1f}) bbox x[{x0},{x1}] y[{y0},{y1}]')
